<?php
namespace App\Console\Commands;
use App\Models\{Department,EditRequest,Leave,TimeClock,User,WorkBreak};
use Illuminate\Console\Command;use Illuminate\Support\Facades\{DB,Storage};
class ImportLegacyRails extends Command {
 protected $signature='legacy:import {--dry-run}';protected $description='Import Rails users, attendance, requests and Active Storage files';
 public function handle():int{$db=DB::connection('legacy');$dry=$this->option('dry-run');$tables=['users','time_clocks','breaks','leaves','edit_requests'];foreach($tables as $table)if(!$db->getSchemaBuilder()->hasTable($table)){$this->error("Legacy table $table was not found.");return self::FAILURE;}$this->info('Legacy rows: '.collect($tables)->map(fn($t)=>"$t=".$db->table($t)->count())->join(', '));if($dry)return self::SUCCESS;
  DB::transaction(function()use($db){$userMap=[];foreach($db->table('users')->orderBy('id')->cursor() as $row){$dept=$row->department?Department::firstOrCreate(['name'=>$row->department],['code'=>str($row->department)->slug('_')->upper(),'active'=>true]):null;$user=User::updateOrCreate(['email'=>$row->email],['name'=>$row->name,'encrypted_password'=>$row->encrypted_password,'phone_number'=>$row->phone_number??null,'address'=>$row->address??null,'role'=>$row->role??'Executive','department'=>$row->department??null,'department_id'=>$dept?->id,'shift_time'=>$row->shift_time??'18:00','status'=>$row->status??null,'employeed'=>$row->employeed??true]);$userMap[$row->id]=$user->id;}
   $clockMap=[];foreach($db->table('time_clocks')->orderBy('id')->cursor() as $row){if(!isset($userMap[$row->user_id]))continue;$clock=TimeClock::updateOrCreate(['user_id'=>$userMap[$row->user_id],'clock_in'=>$row->clock_in],['clock_out'=>$row->clock_out,'total_duration'=>$row->total_duration??null,'status'=>$row->status??null,'break_duration'=>$row->break_duration??null,'current_state'=>$row->current_state??null,'ip_address'=>$row->ip_address??null]);$clockMap[$row->id]=$clock->id;}
   foreach($db->table('breaks')->orderBy('id')->cursor() as $row)if(isset($clockMap[$row->time_clock_id]))WorkBreak::updateOrCreate(['time_clock_id'=>$clockMap[$row->time_clock_id],'break_in'=>$row->break_in],['break_out'=>$row->break_out,'break_type'=>$row->break_type]);
   foreach($db->table('leaves')->orderBy('id')->cursor() as $row)if(isset($userMap[$row->user_id]))Leave::updateOrCreate(['user_id'=>$userMap[$row->user_id],'start_date'=>$row->start_date,'leave_type'=>$row->leave_type],['end_date'=>$row->end_date,'reason'=>$row->reason??null,'status'=>$row->status??'pending_manager','approved_by_manager'=>$row->approved_by_manager??false]);
   foreach($db->table('edit_requests')->orderBy('id')->cursor() as $row)if(isset($userMap[$row->user_id],$clockMap[$row->time_clock_id]))EditRequest::updateOrCreate(['user_id'=>$userMap[$row->user_id],'time_clock_id'=>$clockMap[$row->time_clock_id],'created_at'=>$row->created_at],['requested_clock_in'=>$row->requested_clock_in,'reason'=>$row->reason,'status'=>$row->status??'pending_manager','department'=>$row->department??null,'approved_by_manager'=>$row->approved_by_manager??null,'approved_by_admin'=>$row->approved_by_admin??null,'request_type'=>$row->request_type??'clock_in','break_reason'=>$row->break_reason??null,'resolved_at'=>$row->resolved_at??null]);
  });$this->importFiles($db);$this->info('Legacy Rails data imported successfully.');return self::SUCCESS;}
 private function importFiles($db):void{$root=env('LEGACY_STORAGE_PATH');if(!$root||!is_dir($root)||!$db->getSchemaBuilder()->hasTable('active_storage_attachments'))return;foreach($db->table('active_storage_attachments')->join('active_storage_blobs','active_storage_blobs.id','=','active_storage_attachments.blob_id')->select('active_storage_attachments.*','active_storage_blobs.key','active_storage_blobs.filename')->cursor() as $file){$source=rtrim($root,'/\\').DIRECTORY_SEPARATOR.substr($file->key,0,2).DIRECTORY_SEPARATOR.substr($file->key,2,2).DIRECTORY_SEPARATOR.$file->key;if(!is_file($source))continue;$target='legacy/'.$file->record_type.'/'.$file->record_id.'/'.$file->filename;Storage::disk('public')->put($target,file_get_contents($source));if($file->record_type==='Leave'&&$file->name==='medical_certificate')Leave::whereKey($file->record_id)->update(['medical_certificate_path'=>$target]);if($file->record_type==='User')User::whereKey($file->record_id)->update(['image_path'=>$target]);}}
}
